const messageObj = $json.message || {};
const callbackObj = $json.callback_query || {};

const inputTeks = messageObj.text || callbackObj.data || "";
const telegramId = messageObj.from?.id || callbackObj.from?.id;
const chatId = messageObj.chat?.id || callbackObj.message?.chat?.id;
const photoArray = messageObj.photo || null;

const trimmedText = inputTeks.trim();
const command = trimmedText.split(" ")[0].toLowerCase().split("@")[0];

// Format Tanggal Otomatis (DD/MM/YYYY HH:mm)
const now = new Date();
const tanggalFormatted = now.toLocaleDateString('id-ID') + ' ' + now.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });

function cleanNumber(val) {
  if (!val) return 0;
  const cleaned = String(val).replace(/[^0-9]/g, "");
  return parseInt(cleaned, 10) || 0;
}

function generateKode() {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  let str = "";
  for (let i = 0; i < 4; i++) {
    str += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return `TRX-${str}`;
}

let actionType = "UNKNOWN";
let errorMessage = null;
let guideMessage = null;

let jenisTrans = null;
let kodeTrans = null;
let namaBarang = null;
let metodePembayaran = null;
let jumlah = null;
let satuan = null;
let hargaBarang = null;
let totalPembayaran = null;

// ==========================================
// 0. DETEKSI FOTO / STRUK (DICEK TERLEBIH DAHULU)
// ==========================================
if (photoArray && photoArray.length > 0) {
  actionType = "FOTO";

// 1. Menu Utama (/start & /menu)
} else if (command === "/start" || command === "/menu") {
  actionType = "START";
  guideMessage = `👋 Selamat datang di *PandaiNgaturBot*!

Gunakan tombol menu atau ketik /rekap untuk melihat panduan format pencatatan transaksi.`;

// 2. Panduan Format Pencatatan (/rekap)
} else if (command === "/rekap") {
  actionType = "MODULE_GUIDE";
  guideMessage = `💡 PANDUAN FORMAT PENCATATAN TRANSAKSI

1. CATAT PEMASUKAN (Penjualan):

pemasukan [Nama Barang], [Qty dan Satuan], [Harga Satuan], [Metode]

Contoh:
pemasukan beras, 2kg, 10500, Tunai
pemasukan parfum mykonos, 100pcs, 450000, qris


2. CATAT PENGELUARAN (Pembelian):

pengeluaran [Nama Barang], [Total Harga Beli], [Metode]

Contoh:
pengeluaran Minyak Goreng, 25000, Tunai

3. CATAT PEMASUKAN ATAU PENGELUARAN VIA FOTO

ente ciailah ente, bisa menambahkan foto struk yang sesuai, nanti akan tercatat otomatis dan dikategorikan sebagai pemasukan atau pengeluaran`;

// 3. Export File Excel Rekapitulasi (/lihatfile)
} else if (command === "/lihatfile") {
  actionType = "REKAP";

// 4. Perintah Reset Data (/reset)
} else if (command === "/reset") {
  actionType = "RESET";

// 5. Transaksi Pemasukan (pemasukan)
} else if (command === "pemasukan") {
  const content = trimmedText.replace(/^pemasukan\s+/i, "");
  const parts = content.split(",").map(p => p.trim());

  let qty = 0;
  let unit = "Pcs";

  if (parts[1]) {
    const numPart = parts[1].replace(/[^0-9]/g, "");
    qty = parseInt(numPart, 10) || 0;
    const textPart = parts[1].replace(/[0-9\s]/g, "");
    if (textPart) unit = textPart;
  }

  const harga = cleanNumber(parts[2]);

  // Validasi: minimal 3 bagian (Barang, Qty, Harga) dan angka harus valid
  if (parts.length < 3 || qty <= 0 || harga <= 0) {
    actionType = "INVALID_FORMAT";
    errorMessage = `❌ FORMAT PEMASUKAN SALAH!

Format yang benar (pakai koma):
pemasukan [Nama Barang], [Qty+Satuan], [Harga Satuan], [Metode]

📌 Contoh Benar:
pemasukan beras, 2kg, 10500, Tunai
pemasukan parfum mykonos, 100pcs, 450000, qris`;
  } else {
    actionType = "TRANSACTION";
    jenisTrans = "PENJUALAN";
    kodeTrans = generateKode();

    namaBarang = parts[0];
    jumlah = qty;
    satuan = unit;
    hargaBarang = harga;
    metodePembayaran = parts[3] || "Tunai"; // Mengambil metode dari indeks ke-3 (koma ke-4)
    totalPembayaran = jumlah * hargaBarang;
  }

// 6. Transaksi Pengeluaran (pengeluaran)
} else if (command === "pengeluaran") {
  const content = trimmedText.replace(/^pengeluaran\s+/i, "");
  const parts = content.split(",").map(p => p.trim());

  const total = cleanNumber(parts[1]);

  if (parts.length < 2 || total <= 0) {
    actionType = "INVALID_FORMAT";
    errorMessage = `❌ FORMAT PENGELUARAN SALAH!

Format yang benar (pakai koma):
pengeluaran [Nama Barang], [Total Beli], [Metode]

📌 Contoh Benar:
pengeluaran Minyak Goreng, 25000, Tunai`;
  } else {
    actionType = "TRANSACTION";
    jenisTrans = "PENGELUARAN";
    kodeTrans = generateKode();

    namaBarang = parts[0];
    jumlah = 1;
    satuan = "Pcs";
    totalPembayaran = total;
    hargaBarang = total;
    metodePembayaran = parts[2] || "Tunai";
  }

// 7. Bantuan
} else if (command === "/bantuan") {
  actionType = "MODULE_GUIDE";
  guideMessage = `📞 BANTUAN PANDAINGATURBOT\n\nHubungi CS: @dapoykun\nWhatsapp: https://wa.link/fq9h3w\n\nGunakan /menu untuk kembali.`;

// 8. Perintah Tidak Dikenali
} else {
  actionType = "INVALID_FORMAT";
  errorMessage = `❓ Perintah tidak dikenali.\nKetik /menu untuk melihat panduan penggunaan.`;
}

return [{
  json: {
    timestamp: now.toISOString(),
    tanggal: tanggalFormatted,
    telegram_id: telegramId,
    chat_id: chatId,
    action_type: actionType,
    error_message: errorMessage,
    guide_message: guideMessage,
    reply_text: errorMessage || guideMessage,

    // Tetap pertahankan objek message asli dari Telegram agar foto tidak hilang
    message: messageObj,

    jenis_transaksi: jenisTrans,
    jenis: jenisTrans,
    kode: kodeTrans,
    nama: namaBarang,
    nama_barang: namaBarang,
    metode_pembayaran: metodePembayaran,
    metode: metodePembayaran,
    jumlah: jumlah,
    qty: jumlah,
    satuan: satuan,
    harga_barang: hargaBarang,
    harga: hargaBarang,
    harga_satuan: hargaBarang,
    total_pembayaran: totalPembayaran,
    total: totalPembayaran
  }
}];

