// ========================================================
// PARSER STRUK DENGAN BACA PATH PRESISI (content.parts[0].text)
// ========================================================

// 1. Auto-Generate Kode TRX & Tanggal
function generateKode() {
  const chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
  let str = "";
  for (let i = 0; i < 4; i++) {
    str += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return `TRX-${str}`;
}

const now = new Date();
const tgl = now.getDate();
const bln = now.getMonth() + 1;
const thn = now.getFullYear();
const jam = String(now.getHours()).padStart(2, '0');
const menit = String(now.getMinutes()).padStart(2, '0');
const tanggalFormatted = `${tgl}/${bln}/${thn} ${jam}.${menit}`;

// 2. AMBIL TEKS LANGSUNG DARI PATH KEBANYAKAN GEMINI N8N (SESUAI GAMBAR 3)
const itemData = $input.item.json || {};
let rawText = "";

if (itemData.content && itemData.content.parts && itemData.content.parts[0] && itemData.content.parts[0].text) {
  // Path Presisi Sesuai Gambar 3 mase!
  rawText = itemData.content.parts[0].text; 
} else if (itemData.text) {
  rawText = itemData.text;
} else if (typeof itemData === 'string') {
  rawText = itemData;
} else {
  rawText = JSON.stringify(itemData);
}

rawText = String(rawText || "").trim();

// 3. Parsing JSON secara aman
let parsed = {};
try {
  let cleaned = rawText
    .replace(/```json/gi, '')
    .replace(/```/gi, '')
    .trim();

  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1) {
    cleaned = cleaned.substring(firstBrace, lastBrace + 1);
  }
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {};
}

// Helper Pembersih Angka
function cleanNumber(val) {
  if (typeof val === 'number') return val;
  if (!val) return 0;
  const digits = String(val).replace(/[^0-9]/g, '');
  return parseInt(digits, 10) || 0;
}

// 4. Ambil Nilai Ekstraksi Gemini
const namaBarang = parsed.nama_barang || parsed.produk || parsed.nama || parsed.item || "Pembelian Struk";
const totalHarga = cleanNumber(parsed.total || parsed.subtotal || 0);

const jenis = "PENGELUARAN";
const kodeTrx = generateKode();
const jumlah = 1;
const satuan = "Pcs";
const hargaSatuan = totalHarga;
const hpp = totalHarga;
const keuntungan = -totalHarga;
const metode = parsed.metode || "Tunai";
const totalFormatted = totalHarga > 0 ? totalHarga.toLocaleString('id-ID') : "0";

// 5. Output Siap Disalurkan ke Google Sheets & Telegram
return [{
  json: {
    kode: kodeTrx,
    tanggal: tanggalFormatted,
    jenis: jenis,
    nama_barang: namaBarang,
    keterangan: namaBarang,
    jumlah: jumlah,
    satuan: satuan,
    harga_satuan: hargaSatuan,
    total: totalHarga,
    total_formatted: totalFormatted,
    metode: metode
  }
}];
